  "overview": {
    "text": "The Central Intelligence Agency (CIA) is a U.S. civilian agency that gathers and analyzes intelligence about foreign countries and global issues for national-security decision-makers. Established by the National Security Act of 1947 and formally created on September 18, it was charged with coordinating national intelligence and sharing assessments affecting U.S. security. Its institutional roots include the World War II Office of Strategic Services (OSS) and the postwar Central Intelligence Group (CIG), but the CIA was a distinct successor organization. Today, it collects foreign intelligence, produces analysis, and may conduct covert action when directed by the president. It informs policymakers rather than making policy, and is not a law-enforcement agency—features that distinguish its mission from domestic policing.",
    "source_urls": [
      "https://www.cia.gov/about/",
      "https://www.cia.gov/legacy/cia-history",
      "https://www.archives.gov/research/military/ww2/oss/timeline"
    ]
  },
  "key_facts": [
    {
      "text": "The National Security Act of 1947 established the CIA as an independent civilian agency in the executive branch; September 18, 1947, marks its formal establishment.",
      "source_urls": [
        "https://www.cia.gov/legacy/cia-history",
        "https://www.archives.gov/research/military/ww2/oss/timeline"
      ]
    },
    {
      "text": "The CIA’s predecessors included the World War II Office of Strategic Services and the postwar Central Intelligence Group.",
      "source_urls": [
        "https://www.cia.gov/legacy/cia-history",
        "https://www.archives.gov/research/military/ww2/oss/timeline"
      ]
    },
    {
      "text": "Its work includes collecting foreign intelligence, producing analysis, and conducting covert action when directed by the president.",
      "source_urls": [
        "https://www.cia.gov/about/"
      ]
    },
    {
      "text": "The CIA provides intelligence to policymakers; it does not make policy or operate as a law-enforcement organization.",
      "source_urls": [
        "https://www.cia.gov/about/"
      ]
    },
    {
      "text": "The CIA seal uses an eagle, shield, and compass rose to represent alertness, defense, and global intelligence collection.",
      "source_urls": [
        "https://www.cia.gov/about/"
      ]
    }
  ],
